<style>
.management-page{max-width:1440px;margin:auto;color:#17253c}.management-page h2{font-size:26px;font-weight:750;letter-spacing:-.5px}.management-page h3{font-size:18px;font-weight:700}.management-muted{color:#61718a;font-size:13px;line-height:1.6}.management-panel{background:white;border:1px solid #dde5f0;border-radius:14px;padding:22px;margin-bottom:20px}.management-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin-bottom:20px}.management-card{background:white;border:1px solid #dde5f0;border-radius:14px;padding:20px;min-width:0}.management-card .value{font-size:25px;font-weight:750;margin:7px 0;overflow-wrap:anywhere}.management-period{display:flex;align-items:end;flex-wrap:wrap;gap:14px;margin:22px 0}.management-period label,.management-target label{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:600}.management-period input,.management-target input,.management-target select{border:1px solid #cbd5e1;border-radius:7px;padding:9px 12px;background:white;min-height:40px;max-width:100%}.management-period a{font-size:13px;color:#1d4ed8;padding:10px 0}.management-primary{background:#1d4ed8;color:white;padding:10px 16px;border-radius:8px;font-weight:600;font-size:13px}.management-links{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.management-links button{font-size:12px;border:1px solid #cbd5e1;padding:7px 10px;border-radius:6px;background:#f8fafc}.management-table{width:100%;border-collapse:collapse;font-size:13px}.management-table th{text-align:left;background:#f1f5f9;color:#475569;padding:12px;white-space:nowrap}.management-table td{padding:12px;border-bottom:1px solid #e2e8f0;vertical-align:top}.management-table .number{white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums}.management-badge{display:inline-block;border-radius:6px;padding:4px 8px;font-size:11px;font-weight:700;white-space:nowrap}.management-notice{background:#fff7ed;color:#9a3412;border:1px solid #fed7aa;padding:13px 16px;border-radius:9px;margin:14px 0;font-size:13px}.management-target{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin-top:16px}.management-school-line{display:flex;justify-content:space-between;gap:12px;font-size:13px;padding:7px 0;border-bottom:1px solid #f1f5f9}.management-track{height:7px;border-radius:8px;background:#e2e8f0;margin:8px 0 15px;overflow:hidden}.management-track>div{height:100%;background:#2563eb}.management-scroll{overflow-x:auto}.management-attention{padding:12px 0;border-bottom:1px solid #e2e8f0;font-size:13px}.management-spark{width:100%;height:60px;margin-top:12px}.management-error{color:#b91c1c}.management-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}@media(max-width:850px){.management-pair{grid-template-columns:1fr}.management-panel{padding:15px}.management-page h2{font-size:22px}}
.management-tabs{display:flex;gap:8px;flex-wrap:wrap;border-bottom:1px solid #dbe4f0;padding-bottom:12px;margin:20px 0}.management-tabs button{padding:10px 16px;border-radius:8px;font-size:14px;font-weight:650;background:#f1f5f9;color:#475569}.management-tabs button[aria-selected="true"]{background:#1d4ed8;color:white}.management-page [hidden]{display:none!important}
.management-link-primary{font-size:12px;font-weight:700;color:#1d4ed8;border:1px solid #bfdbfe;background:#eff6ff;padding:7px 11px;border-radius:6px}.management-work-inside{margin-top:12px;font-size:12px;color:#61718a}.management-work-inside summary{cursor:pointer}
.management-bulk{display:flex;flex-wrap:wrap;align-items:end;gap:14px;background:#f8fafc;border:1px solid #dde5f0;border-radius:10px;padding:12px 14px;margin-bottom:14px}.management-bulk label{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:600}.management-bulk select{border:1px solid #cbd5e1;border-radius:7px;padding:8px 10px;background:white}.management-bulk-total{display:flex;flex-direction:column;gap:2px;margin-right:auto;font-size:15px}.management-bulk button[disabled]{opacity:.45;cursor:not-allowed}
.management-months{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-bottom:12px}.management-month{cursor:pointer}.management-month input{position:absolute;opacity:0;pointer-events:none}.management-month span{display:inline-block;padding:6px 11px;border-radius:999px;border:1px solid #cbd5e1;background:#fff;font-size:13px;font-weight:600;color:#334155}.management-month input:checked+span{background:#047857;border-color:#047857;color:#fff}.management-month input:focus-visible+span{outline:2px solid #10b981;outline-offset:2px}.management-month.is-paid span{background:#ecfdf5;border-color:#a7f3d0;color:#047857;cursor:default}
.management-chip-button{border:1px solid #a7f3d0;background:#ecfdf5;color:#065f46;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:700}.management-chip-button:hover{background:#d1fae5}.reg-input{border:1px solid #cbd5e1;border-radius:6px;padding:5px 7px;background:#fff}
.management-period select{border:1px solid #cbd5e1;border-radius:7px;padding:9px 12px;background:white;min-height:40px;max-width:100%}.management-quarter-link{color:#1d4ed8;font-weight:700;white-space:nowrap}.management-selected-quarter td{background:#eff6ff}.management-school-line strong{text-align:right}
</style>
